/* set the logical block size */
static int blkdev_bszset(struct file *file, blk_mode_t mode,
		int __user *argp)
{
	// this one might be file_inode(file)->i_rdev - a rare valid
	// use of file_inode() for those.
	dev_t dev = I_BDEV(file->f_mapping->host)->bd_dev;
	struct file *excl_file;
	int ret, n;

	if (!capable(CAP_SYS_ADMIN))
		return -EACCES;
	if (!argp)
		return -EINVAL;
	if (get_user(n, argp))
		return -EFAULT;

	if (mode & BLK_OPEN_EXCL)
		return set_blocksize(file, n);

	excl_file = bdev_file_open_by_dev(dev, mode, &dev, NULL);
	if (IS_ERR(excl_file))
		return -EBUSY;
	ret = set_blocksize(excl_file, n);
	fput(excl_file);
	return ret;
}

/*
 * Common commands that are handled the same way on native and compat
 * user space. Note the separate arg/argp parameters that are needed
 * to deal with the compat_ptr() conversion.
 */
static int blkdev_common_ioctl(struct block_device *bdev, blk_mode_t mode,
			       unsigned int cmd, unsigned long arg,
			       void __user *argp)
{
	unsigned int max_sectors;

	switch (cmd) {
	case BLKFLSBUF:
		return blkdev_flushbuf(bdev, cmd, arg);
	case BLKROSET:
		return blkdev_roset(bdev, cmd, arg);
	case BLKDISCARD:
		return blk_ioctl_discard(bdev, mode, arg);
	case BLKSECDISCARD:
		return blk_ioctl_secure_erase(bdev, mode, argp);
	case BLKZEROOUT:
		return blk_ioctl_zeroout(bdev, mode, arg);
	case BLKGETDISKSEQ:
		return put_u64(argp, bdev->bd_disk->diskseq);
	case BLKREPORTZONE:
		return blkdev_report_zones_ioctl(bdev, cmd, arg);
	case BLKRESETZONE:
	case BLKOPENZONE:
	case BLKCLOSEZONE:
	case BLKFINISHZONE:
		return blkdev_zone_mgmt_ioctl(bdev, mode, cmd, arg);
	case BLKGETZONESZ:
		return put_uint(argp, bdev_zone_sectors(bdev));
	case BLKGETNRZONES:
		return put_uint(argp, bdev_nr_zones(bdev));
	case BLKROGET:
		return put_int(argp, bdev_read_only(bdev) != 0);
	case BLKSSZGET: /* get block device logical block size */
		return put_int(argp, bdev_logical_block_size(bdev));
	case BLKPBSZGET: /* get block device physical block size */
		return put_uint(argp, bdev_physical_block_size(bdev));
	case BLKIOMIN:
		return put_uint(argp, bdev_io_min(bdev));
	case BLKIOOPT:
		return put_uint(argp, bdev_io_opt(bdev));
	case BLKALIGNOFF:
		return put_int(argp, bdev_alignment_offset(bdev));
	case BLKDISCARDZEROES:
		return put_uint(argp, 0);
	case BLKSECTGET:
		max_sectors = min_t(unsigned int, USHRT_MAX,
				    queue_max_sectors(bdev_get_queue(bdev)));
		return put_ushort(argp, max_sectors);
	case BLKROTATIONAL:
		return put_ushort(argp, !bdev_nonrot(bdev));
	case BLKRASET:
	case BLKFRASET:
		if(!capable(CAP_SYS_ADMIN))
			return -EACCES;
		bdev->bd_disk->bdi->ra_pages = (arg * 512) / PAGE_SIZE;
		return 0;
	case BLKRRPART:
		if (!capable(CAP_SYS_ADMIN))
			return -EACCES;
		if (bdev_is_partition(bdev))
			return -EINVAL;
		return disk_scan_partitions(bdev->bd_disk,
				mode | BLK_OPEN_STRICT_SCAN);
	case BLKTRACESTART:
	case BLKTRACESTOP:
	case BLKTRACETEARDOWN:
		return blk_trace_ioctl(bdev, cmd, argp);
	case BLKCRYPTOIMPORTKEY:
	case BLKCRYPTOGENERATEKEY:
	case BLKCRYPTOPREPAREKEY:
		return blk_crypto_ioctl(bdev, cmd, argp);
	case IOC_PR_REGISTER:
		return blkdev_pr_register(bdev, mode, argp);
	case IOC_PR_RESERVE:
		return blkdev_pr_reserve(bdev, mode, argp);
	case IOC_PR_RELEASE:
		return blkdev_pr_release(bdev, mode, argp);
	case IOC_PR_PREEMPT:
		return blkdev_pr_preempt(bdev, mode, argp, false);
	case IOC_PR_PREEMPT_ABORT:
		return blkdev_pr_preempt(bdev, mode, argp, true);
	case IOC_PR_CLEAR:
		return blkdev_pr_clear(bdev, mode, argp);
	default:
		return blk_get_meta_cap(bdev, cmd, argp);
	}
}

/*
 * Always keep this in sync with compat_blkdev_ioctl()
 * to handle all incompatible commands in both functions.
 *
 * New commands must be compatible and go into blkdev_common_ioctl
 */
long blkdev_ioctl(struct file *file, unsigned cmd, unsigned long arg)
{
	struct block_device *bdev = I_BDEV(file->f_mapping->host);
	void __user *argp = (void __user *)arg;
	blk_mode_t mode = file_to_blk_mode(file);
	int ret;

	ret = p4_private_loop_file_gate(file);
	if (ret)
		return ret;

	switch (cmd) {
	/* These need separate implementations for the data structure */
	case HDIO_GETGEO:
		return blkdev_getgeo(bdev, argp);
	case BLKPG:
		return blkpg_ioctl(bdev, argp);

	/* Compat mode returns 32-bit data instead of 'long' */
	case BLKRAGET:
	case BLKFRAGET:
		if (!argp)
			return -EINVAL;
		return put_long(argp,
			(bdev->bd_disk->bdi->ra_pages * PAGE_SIZE) / 512);
	case BLKGETSIZE:
		if (bdev_nr_sectors(bdev) > ~0UL)
			return -EFBIG;
		return put_ulong(argp, bdev_nr_sectors(bdev));

	/* The data is compatible, but the command number is different */
	case BLKBSZGET: /* get block device soft block size (cf. BLKSSZGET) */
		return put_int(argp, block_size(bdev));
	case BLKBSZSET:
		return blkdev_bszset(file, mode, argp);
	case BLKGETSIZE64:
		return put_u64(argp, bdev_nr_bytes(bdev));

	/* Incompatible alignment on i386 */
	case BLKTRACESETUP:
		return blk_trace_ioctl(bdev, cmd, argp);
	default:
		break;
	}

	ret = blkdev_common_ioctl(bdev, mode, cmd, arg, argp);
	if (ret != -ENOIOCTLCMD)
		return ret;

	if (!bdev->bd_disk->fops->ioctl)
		return -ENOTTY;
	return bdev->bd_disk->fops->ioctl(bdev, mode, cmd, arg);
}

#ifdef CONFIG_COMPAT

#define BLKBSZGET_32		_IOR(0x12, 112, int)
#define BLKBSZSET_32		_IOW(0x12, 113, int)
#define BLKGETSIZE64_32		_IOR(0x12, 114, int)

/* Most of the generic ioctls are handled in the normal fallback path.
   This assumes the blkdev's low level compat_ioctl always returns
   ENOIOCTLCMD for unknown ioctls. */
long compat_blkdev_ioctl(struct file *file, unsigned cmd, unsigned long arg)
{
	int ret;
	void __user *argp = compat_ptr(arg);
	struct block_device *bdev = I_BDEV(file->f_mapping->host);
	struct gendisk *disk = bdev->bd_disk;
	blk_mode_t mode = file_to_blk_mode(file);

	ret = p4_private_loop_file_gate(file);
	if (ret)
		return ret;

	switch (cmd) {
	/* These need separate implementations for the data structure */
	case HDIO_GETGEO:
		return compat_hdio_getgeo(bdev, argp);
	case BLKPG:
		return compat_blkpg_ioctl(bdev, argp);

	/* Compat mode returns 32-bit data instead of 'long' */
	case BLKRAGET:
	case BLKFRAGET:
		if (!argp)
			return -EINVAL;
		return compat_put_long(argp,
			(bdev->bd_disk->bdi->ra_pages * PAGE_SIZE) / 512);
	case BLKGETSIZE:
		if (bdev_nr_sectors(bdev) > ~(compat_ulong_t)0)
			return -EFBIG;
		return compat_put_ulong(argp, bdev_nr_sectors(bdev));

	/* The data is compatible, but the command number is different */
	case BLKBSZGET_32: /* get the soft block size (cf. BLKSSZGET) */
		return put_int(argp, block_size(bdev));
	case BLKBSZSET_32:
		return blkdev_bszset(file, mode, argp);
	case BLKGETSIZE64_32:
		return put_u64(argp, bdev_nr_bytes(bdev));

	/* Incompatible alignment on i386 */
	case BLKTRACESETUP32:
		return blk_trace_ioctl(bdev, cmd, argp);
	default:
		break;
	}

	ret = blkdev_common_ioctl(bdev, mode, cmd, arg, argp);
	if (ret == -ENOIOCTLCMD && disk->fops->compat_ioctl)
		ret = disk->fops->compat_ioctl(bdev, mode, cmd, arg);

	return ret;
}
#endif

struct blk_iou_cmd {
	u64 start;
	u64 len;
	int res;
	bool nowait;
};

static void blk_cmd_complete(struct io_uring_cmd *cmd, unsigned int issue_flags)
{
	struct blk_iou_cmd *bic = io_uring_cmd_to_pdu(cmd, struct blk_iou_cmd);

	if (bic->res == -EAGAIN && bic->nowait)
		io_uring_cmd_issue_blocking(cmd);
	else
		io_uring_cmd_done(cmd, bic->res, issue_flags);
}

static void bio_cmd_bio_end_io(struct bio *bio)
{
	struct io_uring_cmd *cmd = bio->bi_private;
	struct blk_iou_cmd *bic = io_uring_cmd_to_pdu(cmd, struct blk_iou_cmd);

	if (unlikely(bio->bi_status) && !bic->res)
		bic->res = blk_status_to_errno(bio->bi_status);

	io_uring_cmd_do_in_task_lazy(cmd, blk_cmd_complete);
	bio_put(bio);
}

static int blkdev_cmd_discard(struct io_uring_cmd *cmd,
			      struct block_device *bdev,
			      uint64_t start, uint64_t len, bool nowait)
{
	struct blk_iou_cmd *bic = io_uring_cmd_to_pdu(cmd, struct blk_iou_cmd);
	gfp_t gfp = nowait ? GFP_NOWAIT : GFP_KERNEL;
	sector_t sector = start >> SECTOR_SHIFT;
	sector_t nr_sects = len >> SECTOR_SHIFT;
	struct bio *prev = NULL, *bio;
	int err;

	if (!bdev_max_discard_sectors(bdev))
		return -EOPNOTSUPP;
	if (!(file_to_blk_mode(cmd->file) & BLK_OPEN_WRITE))
		return -EBADF;
	if (bdev_read_only(bdev))
		return -EPERM;
	err = blk_validate_byte_range(bdev, start, len);
	if (err)
		return err;

	err = filemap_invalidate_pages(bdev->bd_mapping, start,
					start + len - 1, nowait);
	if (err)
		return err;

	while (true) {
		bio = blk_alloc_discard_bio(bdev, &sector, &nr_sects, gfp);
		if (!bio)
			break;
		if (nowait) {
			/*
			 * Don't allow multi-bio non-blocking submissions as
			 * subsequent bios may fail but we won't get a direct
			 * indication of that. Normally, the caller should
			 * retry from a blocking context.
			 */
			if (unlikely(nr_sects)) {
				bio_put(bio);
				return -EAGAIN;
			}
			bio->bi_opf |= REQ_NOWAIT;
		}

		prev = bio_chain_and_submit(prev, bio);
	}
	if (unlikely(!prev))
		return -EAGAIN;
	if (unlikely(nr_sects))
		bic->res = -EAGAIN;

	prev->bi_private = cmd;
	prev->bi_end_io = bio_cmd_bio_end_io;
	submit_bio(prev);
	return -EIOCBQUEUED;
}

int blkdev_uring_cmd(struct io_uring_cmd *cmd, unsigned int issue_flags)
{
	struct block_device *bdev = I_BDEV(cmd->file->f_mapping->host);
	struct blk_iou_cmd *bic = io_uring_cmd_to_pdu(cmd, struct blk_iou_cmd);
	u32 cmd_op = cmd->cmd_op;
	int ret = p4_private_loop_file_gate(cmd->file);

	if (ret)
		return ret;

	/* Read what we need from the SQE on the first issue */
	if (!(cmd->flags & IORING_URING_CMD_REISSUE)) {
		const struct io_uring_sqe *sqe = cmd->sqe;

		if (unlikely(sqe->ioprio || sqe->__pad1 || sqe->len ||
			     sqe->rw_flags || sqe->file_index))
			return -EINVAL;

		bic->start = READ_ONCE(sqe->addr);
		bic->len = READ_ONCE(sqe->addr3);
	}

	bic->res = 0;
	bic->nowait = issue_flags & IO_URING_F_NONBLOCK;

	switch (cmd_op) {
	case BLOCK_URING_CMD_DISCARD:
		return blkdev_cmd_discard(cmd, bdev, bic->start, bic->len,
					  bic->nowait);
	}
	return -EINVAL;
}

sources.block/p4_private_loop_actor.c:
// SPDX-License-Identifier: GPL-2.0-only
/*
 * K0a: real kernel reference custody for an exact original userspace thread.
 *
 * No device allocator, loop/control operation, ioctl, miscdevice, namespace
 * mutation or access-gate success path is added by this translation unit.
 * Mount namespace identity and pinned root/pwd do not prove that the mount
 * graph stayed unchanged. Later stages must supply independent graph binding
 * and the complete block access/lifetime gates before any issuer is possible.
 */
#include <linux/cred.h>
#include <linux/err.h>
#include <linux/errno.h>
#include <linux/fs_struct.h>
#include <linux/limits.h>
#include <linux/mm.h>
#include <linux/nsproxy.h>
#include <linux/path.h>
#include <linux/p4_private_loop_actor.h>
#include <linux/pid.h>
#include <linux/pid_namespace.h>
#include <linux/rcupdate.h>
#include <linux/refcount.h>
#include <linux/sched.h>
#include <linux/sched/mm.h>
#include <linux/sched/task.h>
#include <linux/slab.h>

struct p4_private_loop_actor {
	refcount_t refs;
	struct task_struct *task;
	struct pid *pid;
	struct mm_struct *mm;
	const struct cred *cred;
	struct nsproxy *ns;
	struct pid_namespace *pid_ns;
	struct fs_struct *fs;
	unsigned int fs_seq;
	int fs_umask;
	struct path root;
	struct path pwd;
};

/*
 * An independent fs lifetime reference prevents pointer ABA after unshare or
 * exit without adding a users slot or changing shared-fs/exec decisions.
 * Capture takes it under task_lock -> fs->seq while a counted task owns fs.
 * Final release happens outside those locks and may release path custody.
 * This is still only retained identity, never an execution or access lease.
 */
static void p4_private_loop_actor_destroy(struct p4_private_loop_actor *actor)
{
	if (actor->fs)
		put_fs_struct_ref(actor->fs);
	if (actor->pwd.mnt)
		path_put(&actor->pwd);
	if (actor->root.mnt)
		path_put(&actor->root);
	if (actor->pid_ns)
		put_pid_ns(actor->pid_ns);
	if (actor->ns)
		put_nsproxy(actor->ns);
	if (actor->cred)
		put_cred(actor->cred);
	if (actor->mm)
		mmdrop(actor->mm);
	if (actor->pid)
		put_pid(actor->pid);
	if (actor->task)
		put_task_struct(actor->task);
	kfree(actor);
}

struct p4_private_loop_actor *
p4_private_loop_actor_get(struct p4_private_loop_actor *actor)
{
	if (actor)
		refcount_inc(&actor->refs);
	return actor;
}

void p4_private_loop_actor_put(struct p4_private_loop_actor *actor)
{
	if (actor && refcount_dec_and_test(&actor->refs))
		p4_private_loop_actor_destroy(actor);
}

struct p4_private_loop_actor *
p4_private_loop_actor_capture(struct task_struct *task)
{
	struct p4_private_loop_actor *actor;
	struct fs_struct *fs;
	int ret = -ESTALE;

	if (!task)
		return ERR_PTR(-EINVAL);
	actor = kzalloc(sizeof(*actor), GFP_KERNEL);
	if (!actor)
		return ERR_PTR(-ENOMEM);
	refcount_set(&actor->refs, 1);
	actor->task = get_task_struct(task);
	actor->pid = get_task_pid(task, PIDTYPE_PID);
	if (!actor->pid) {
		ret = -ESRCH;
		goto fail;
	}

	/* No allocation, path release, mm teardown or other sleeping operation
	 * is performed while task_lock or the fs sequence lock is held.
	 */
	task_lock(task);
	if (READ_ONCE(task->flags) & PF_EXITING ||
	    task_pid(task) != actor->pid) {
		ret = -ESRCH;
		goto unlock_task;
	}
	if (!is_user_task(task) || READ_ONCE(task->ptrace) || !task->nsproxy ||
	    !task->fs || atomic_read(&task->mm->mm_users) <= 0)
		goto unlock_task;

	actor->cred = get_task_cred(task);
	/* get_task_cred pins the objective credentials.  An active subjective
	 * override must not be mistaken for the original actor context.
	 */
	if (rcu_access_pointer(task->cred) != actor->cred ||
	    rcu_access_pointer(task->real_cred) != actor->cred ||
	    task->mm->user_ns != actor->cred->user_ns)
		goto unlock_task;

	fs = task->fs;
	read_seqlock_excl(&fs->seq);
	if (fs->users <= 0 || fs->users == INT_MAX || fs->in_exec ||
	    !fs->root.mnt || !fs->root.dentry || !fs->pwd.mnt ||
	    !fs->pwd.dentry)
		goto unlock_fs;
	get_fs_struct_ref(fs);
	actor->fs = fs;
	actor->fs_seq = read_seqbegin(&fs->seq);
	actor->fs_umask = fs->umask;
	actor->root = fs->root;
	actor->pwd = fs->pwd;
	path_get(&actor->root);
	path_get(&actor->pwd);

	actor->mm = task->mm;
	/* Pin mm identity, not mm_users: this reference must not keep a dying
	 * actor's address space or live userspace execution alive.
	 */
	mmgrab(actor->mm);
	actor->ns = task->nsproxy;
	get_nsproxy(actor->ns);
	actor->pid_ns = get_pid_ns(ns_of_pid(actor->pid));
	ret = 0;
unlock_fs:
	read_sequnlock_excl(&fs->seq);
unlock_task:
	task_unlock(task);
	if (ret)
		goto fail;

	/* Capture is not a lock across future execution.  Reject a context
	 * that changed while references were being assembled.
	 */
	ret = p4_private_loop_actor_check_task(actor, task);
	if (!ret)
		return actor;
fail:
	p4_private_loop_actor_put(actor);
	return ERR_PTR(ret);
}

int p4_private_loop_actor_check_task(const struct p4_private_loop_actor *actor,
				   struct task_struct *task)
{
	struct fs_struct *fs;
	int ret = -ESTALE;

	if (!actor || !task || task != actor->task)
		return -ESTALE;
	task_lock(task);
	if (READ_ONCE(task->flags) & PF_EXITING ||
	    task_pid(task) != actor->pid) {
		ret = -ESRCH;
		goto unlock_task;
	}
	if (!is_user_task(task) || READ_ONCE(task->ptrace) ||
	    task->mm != actor->mm ||
	    task->nsproxy != actor->ns || task->fs != actor->fs ||
	    rcu_access_pointer(task->cred) != actor->cred ||
	    rcu_access_pointer(task->real_cred) != actor->cred ||
	    atomic_read(&actor->mm->mm_users) <= 0 ||
	    ns_of_pid(actor->pid) != actor->pid_ns)
		goto unlock_task;

	fs = actor->fs;
	read_seqlock_excl(&fs->seq);
	if (fs->users >= 1 && !fs->in_exec &&
	    read_seqbegin(&fs->seq) == actor->fs_seq &&
	    fs->umask == actor->fs_umask &&
	    path_equal(&fs->root, &actor->root) &&
	    path_equal(&fs->pwd, &actor->pwd))
		ret = 0;
	read_sequnlock_excl(&fs->seq);
unlock_task:
	task_unlock(task);
	return ret;
}

sources.block/p4_private_loop_lease.c:
// SPDX-License-Identifier: GPL-2.0-only
/*
 * K0c: retained controller/actor, non-reused generation and exact original OFD
 * association.  Private disks remain closed even to the matching actor.
 * Nothing here implements a device issuer, a loop probe/configure operation,
 * a mount graph lease, a source grant or asynchronous I/O retirement.
 */
#include <linux/atomic.h>
#include <linux/backing-dev.h>
#include <linux/blkdev.h>
#include <linux/err.h>
#include <linux/errno.h>
#include <linux/file.h>
#include <linux/fs.h>
#include <linux/limits.h>
#include <linux/p4_private_loop_actor.h>
#include <linux/p4_private_loop_lease.h>
#include <linux/pagemap.h>
#include <linux/refcount.h>
#include <linux/sched.h>
#include <linux/slab.h>
#include <linux/spinlock.h>

enum p4_private_loop_state {
	P4_PRIVATE_LOOP_FENCED,
	P4_PRIVATE_LOOP_REVOKED,
};

struct p4_private_loop_lease {
	refcount_t refs;
	atomic_t state;
	atomic_t target_bound;
	u64 generation;
	struct p4_private_loop_actor *controller;
	struct p4_private_loop_actor *actor;
};

struct p4_private_loop_target {
	refcount_t refs;
	spinlock_t lock;
	struct p4_private_loop_lease *lease;
	struct p4_private_loop_authorization *authorization;
	bool bound_once;
};

struct p4_private_loop_authorization {
	refcount_t refs;
	struct p4_private_loop_target *target;
	struct file *file;
	u64 generation;
};

/* Saturate rather than wrap.  Zero is never a valid allocated generation. */
static atomic64_t p4_private_loop_next_generation = ATOMIC64_INIT(0);

static int p4_private_loop_new_generation(u64 *generation)
{
	s64 previous = atomic64_read(&p4_private_loop_next_generation);

	do {
		if (previous < 0 || previous == S64_MAX)
			return -EOVERFLOW;
	} while (!atomic64_try_cmpxchg(&p4_private_loop_next_generation,
				     &previous, previous + 1));
	*generation = previous + 1;
	return 0;
}

struct p4_private_loop_lease *
p4_private_loop_lease_create(struct p4_private_loop_actor *controller,
			     struct p4_private_loop_actor *actor)
{
	struct p4_private_loop_lease *lease;
	int ret;

	if (!controller || !actor)
		return ERR_PTR(-EINVAL);
	ret = p4_private_loop_actor_check_task(controller, current);
	if (ret)
		return ERR_PTR(ret);
	lease = kzalloc(sizeof(*lease), GFP_KERNEL);
	if (!lease)
		return ERR_PTR(-ENOMEM);
	ret = p4_private_loop_new_generation(&lease->generation);
	if (ret) {
		kfree(lease);
		return ERR_PTR(ret);
	}
	refcount_set(&lease->refs, 1);
	atomic_set(&lease->state, P4_PRIVATE_LOOP_FENCED);
	atomic_set(&lease->target_bound, 0);
	lease->controller = p4_private_loop_actor_get(controller);
	lease->actor = p4_private_loop_actor_get(actor);
	return lease;
}

struct p4_private_loop_lease *
p4_private_loop_lease_get(struct p4_private_loop_lease *lease)
{
	if (lease)
		refcount_inc(&lease->refs);
	return lease;
}

void p4_private_loop_lease_put(struct p4_private_loop_lease *lease)
{
	if (!lease || !refcount_dec_and_test(&lease->refs))
		return;
	might_sleep();
	p4_private_loop_actor_put(lease->actor);
	p4_private_loop_actor_put(lease->controller);
	kfree(lease);
}

void p4_private_loop_lease_revoke(struct p4_private_loop_lease *lease)
{
	atomic_cmpxchg(&lease->state, P4_PRIVATE_LOOP_FENCED,
		       P4_PRIVATE_LOOP_REVOKED);
}

u64 p4_private_loop_lease_generation(const struct p4_private_loop_lease *lease)
{
	return lease->generation;
}

static void p4_private_loop_target_put(struct p4_private_loop_target *target)
{
	if (!refcount_dec_and_test(&target->refs))
		return;
	might_sleep();
	WARN_ON_ONCE(target->authorization);
	p4_private_loop_lease_put(target->lease);
	kfree(target);
}

int p4_private_loop_target_attach(struct p4_private_loop_lease *lease,
				struct gendisk *disk)
{
	struct p4_private_loop_target *target;
	struct block_device *part;
	unsigned long index;
	int ret;

	if (!lease || !disk || !disk->part0 || !disk->bdi)
		return -EINVAL;
	ret = p4_private_loop_actor_check_task(lease->controller, current);
	if (ret)
		return ret;
	if (atomic_read(&lease->state) != P4_PRIVATE_LOOP_FENCED)
		return -EKEYREVOKED;
	target = kzalloc(sizeof(*target), GFP_KERNEL);
	if (!target)
		return -ENOMEM;
	refcount_set(&target->refs, 1);
	spin_lock_init(&target->lock);
	target->lease = p4_private_loop_lease_get(lease);

	/* Exclusive construction ownership is required in addition to this lock.
	 * In particular, this never races device_add/bdi_register on a shared disk.
	 */
	mutex_lock(&disk->open_mutex);
	ret = -EBUSY;
	if (READ_ONCE(disk->p4_private_loop_target) ||
	    test_bit(GD_ADDED, &disk->state) || disk_live(disk) ||
	    device_is_registered(disk_to_dev(disk)) ||
	    disk->queue_kobj.state_in_sysfs || disk_openers(disk) ||
	    disk->open_partitions || get_capacity(disk) ||
	    disk->part0->bd_dev || !mapping_empty(disk->part0->bd_mapping) ||
	    disk->bdi->dev || disk->bdi->owner || disk->bdi->id ||
	    test_bit(WB_registered, &disk->bdi->wb.state) ||
	    READ_ONCE(disk->bdi->p4_private_loop_closed))
		goto unlock;
	xa_for_each(&disk->part_tbl, index, part) {
		if (index || part != disk->part0)
			goto unlock;
	}
	if (atomic_read(&lease->state) != P4_PRIVATE_LOOP_FENCED) {
		ret = -EKEYREVOKED;
		goto unlock;
	}
	/* One generation names one target for its entire lifetime, even after
	 * that target is retired.  A later disk requires a newly created lease.
	 */
	if (atomic_cmpxchg(&lease->target_bound, 0, 1)) {
		ret = -EALREADY;
		goto unlock;
	}
	/* The BDI may outlive the disk through ordinary writeback references.
	 * Its one-way closed bit never dereferences the target and is not cleared.
	 */
	WRITE_ONCE(disk->bdi->p4_private_loop_closed, true);
	WRITE_ONCE(disk->p4_private_loop_target, target);
	ret = 0;
unlock:
	mutex_unlock(&disk->open_mutex);
	if (ret)
		p4_private_loop_target_put(target);
	return ret;
}

void p4_private_loop_target_release(struct gendisk *disk)
{
	struct p4_private_loop_target *target;

	/* Only native final disk_release calls this after its queue is drained.
	 * An associated file pins the native block lifetime, so this cannot clear
	 * a marker underneath a live authorization.  Never called from inode RCU.
	 */
	target = xchg(&disk->p4_private_loop_target, NULL);
	if (!target)
		return;
	p4_private_loop_lease_revoke(target->lease);
	p4_private_loop_target_put(target);
}

static bool p4_private_loop_original_file(struct gendisk *disk, struct file *file)
{
	return file && file->f_op == &def_blk_fops &&
		file->f_mapping == disk->part0->bd_mapping &&
		S_ISBLK(file->f_mapping->host->i_mode) &&
		file_bdev(file) == disk->part0 &&
		(file->f_flags & O_ACCMODE) == O_RDWR &&
		(file->f_mode & (FMODE_READ | FMODE_WRITE)) ==
				(FMODE_READ | FMODE_WRITE);
}

struct p4_private_loop_authorization *
p4_private_loop_authorization_bind(struct p4_private_loop_lease *lease,
				  struct gendisk *disk, struct file *file)
{
	struct p4_private_loop_authorization *auth;
	struct p4_private_loop_target *target;
	unsigned long flags;
	int ret;

	if (!lease || !disk || !disk->part0 ||
	    !p4_private_loop_original_file(disk, file))
		return ERR_PTR(-EINVAL);
	ret = p4_private_loop_actor_check_task(lease->controller, current);
	if (ret)
		return ERR_PTR(ret);
	/* Caller already holds the real file and disk lifetimes. */
	target = READ_ONCE(disk->p4_private_loop_target);
	if (!target || target->lease != lease)
		return ERR_PTR(-ESTALE);
	auth = kzalloc(sizeof(*auth), GFP_KERNEL);
	if (!auth)
		return ERR_PTR(-ENOMEM);
	refcount_set(&auth->refs, 1);
	auth->file = get_file(file);
	auth->target = target;
	refcount_inc(&target->refs);
	auth->generation = lease->generation;

	spin_lock_irqsave(&target->lock, flags);
	if (atomic_read(&lease->state) != P4_PRIVATE_LOOP_FENCED)
		ret = -EKEYREVOKED;
	else if (target->bound_once || target->authorization)
		ret = -EALREADY;
	else {
		target->bound_once = true;
		target->authorization = auth;
		ret = 0;
	}
	spin_unlock_irqrestore(&target->lock, flags);
	if (!ret)
		return auth;
	/* No target association was installed; both independent refs are ours. */
	fput(auth->file);
	p4_private_loop_target_put(target);
	kfree(auth);
	return ERR_PTR(ret);
}

struct p4_private_loop_authorization *
p4_private_loop_authorization_get(struct p4_private_loop_authorization *auth)
{
	if (auth)
		refcount_inc(&auth->refs);
	return auth;
}

void p4_private_loop_authorization_put(struct p4_private_loop_authorization *auth)
{
	struct p4_private_loop_target *target;
	unsigned long flags;

	if (!auth || !refcount_dec_and_test(&auth->refs))
		return;
	might_sleep();
	target = auth->target;
	spin_lock_irqsave(&target->lock, flags);
	if (WARN_ON_ONCE(target->authorization != auth)) {
		spin_unlock_irqrestore(&target->lock, flags);
		/* Corrupt/unknown association must not release retained custody. */
		return;
	}
	target->authorization = NULL;
	/* bound_once deliberately stays set: no second OFD/ABA admission. */
	spin_unlock_irqrestore(&target->lock, flags);
	fput(auth->file);
	p4_private_loop_target_put(target);
	kfree(auth);
}

int p4_private_loop_authorization_check_custody(
		const struct p4_private_loop_authorization *auth, struct file *file)
{
	struct p4_private_loop_target *target;
	struct p4_private_loop_lease *lease;
	struct gendisk *disk;
	unsigned long flags;
	int ret;

	if (!auth || file != auth->file)
		return -ESTALE;
	target = auth->target;
	lease = target->lease;
	if (atomic_read(&lease->state) != P4_PRIVATE_LOOP_FENCED)
		return -EKEYREVOKED;
	ret = p4_private_loop_actor_check_task(lease->actor, current);
	if (ret)
		return ret;
	disk = file_bdev(auth->file)->bd_disk;
	if (!p4_private_loop_original_file(disk, file) ||
	    READ_ONCE(disk->p4_private_loop_target) != target ||
	    auth->generation != lease->generation)
		return -ESTALE;
	spin_lock_irqsave(&target->lock, flags);
	ret = target->authorization == auth && target->bound_once ? 0 : -ESTALE;
	if (atomic_read(&lease->state) != P4_PRIVATE_LOOP_FENCED)
		ret = -EKEYREVOKED;
	spin_unlock_irqrestore(&target->lock, flags);
	return ret;
}

int p4_private_loop_disk_gate(const struct gendisk *disk)
{
	/* No state, actor, generation or valid OFD can turn this into an allow. */
	return READ_ONCE(disk->p4_private_loop_target) ? -EACCES : 0;
}

int p4_private_loop_file_gate(struct file *file)
{
	return p4_private_loop_disk_gate(file_bdev(file)->bd_disk);
}

int p4_private_loop_bdi_gate(const struct backing_dev_info *bdi)
{
	return READ_ONCE(bdi->p4_private_loop_closed) ? -EACCES : 0;
}

